const texto = $input.item.json.output || 'Lo siento, no he podido procesar tu pregunta.';

// Eliminar caracteres Markdown que rompen el parseo de la API de Telegram
const textoLimpio = texto
  .replace(/\*\*/g, '')
  .replace(/\*/g, '')
  .replace(/\_\_/g, '')
  .replace(/\_/g, '')
  .replace(/\[([^\]]+)\]\([^\)]+\)/g, '$1');

return [{ json: { texto: textoLimpio } }];
